  -- ── Inmobiliario (Real Estate) ────────────────────────────────────────────────

  INSERT INTO kefy_content_library (industry_id, content_type, title, body, hashtags, image_prompt, source, language) VALUES
  (ind_inmob, 'post',
   '5 errores al buscar departamento',
   'Buscar depa nuevo puede ser estresante. Estos son los 5 errores más comunes que vemos en nuestros clientes:

1. No definir presupuesto antes de visitar
2. Ignorar los gastos comunes
3. No revisar la orientación del sol
4. Firmar sin leer la letra chica
5. No investigar el barrio de noche

¿Cuál de estos has cometido? Cuéntanos en los comentarios.

[Agenda una asesoría gratuita]',
   ARRAY['#inmobiliaria', '#departamentos', '#bienesraices', '#arriendos', '#tipshogar'],
   'Modern apartment building exterior at golden hour, warm sunlight reflecting off glass windows, urban residential neighborhood, photorealistic architectural photography',
   'seed', 'es'),

  (ind_inmob, 'carousel',
   'Checklist antes de firmar un arriendo',
   'Antes de firmar tu contrato de arriendo, asegúrate de revisar cada uno de estos puntos. Un error puede costarte meses de problemas.

