  INSERT INTO kefy_content_library (industry_id, content_type, title, body, hashtags, image_prompt, source, language) VALUES
  (ind_salud, 'post',
   'El mito del "no tengo tiempo para hacer ejercicio"',
   'No necesitas 1 hora en el gimnasio para estar saludable.

